{-| @Backend.Runtime.Host.Callback — keeps native callbacks and foreign-call
    failure scopes behind the run gate. -}
module Pudu.Backend.Runtime.Host.Callback (hostCallbackParts, callbackRuntime) where

import Data.Text (Text)

hostCallbackParts :: [(Text, [Text], [Text])]
hostCallbackParts =
  [("host_callback", ["host_gate", "fail", "text_literal", "text_copy", "text_retain", "text_release"], [])]

callbackRuntime :: [Text]
callbackRuntime =
  [ "#include <setjmp.h>"
  , "#include <stdatomic.h>"
  , ""
  , "typedef struct pudu_callback_entry {"
  , "  struct pudu_callback_entry *next;"
  , "  uintptr_t key;"
  , "  const void *identity;"
  , "  pudu_box *handler;"
  , "  void (*drop)(pudu_box *);"
  , "  size_t active, leases, waiters;"
  , "  int retired, warned, observed, failed;"
  , "  pudu_text failure;"
  , "  pudu_site failure_site;"
  , "  size_t members;"
  , "  size_t fields[];"
  , "} pudu_callback_entry;"
  , ""
  , "typedef struct pudu_callback_scope {"
  , "  struct pudu_callback_scope *previous;"
  , "  pudu_text failure;"
  , "  pudu_site failure_site;"
  , "  int failed;"
  , "} pudu_callback_scope;"
  , ""
  , "typedef struct pudu_callback_invocation {"
  , "  struct pudu_callback_invocation *previous;"
  , "  pudu_callback_entry *entry;"
  , "  jmp_buf escape;"
  , "} pudu_callback_invocation;"
  , ""
  , "/* Failures nobody observed, warned of at exit after any report. */"
  , "typedef struct pudu_callback_unobserved {"
  , "  struct pudu_callback_unobserved *next;"
  , "  pudu_text failure;"
  , "  pudu_site site;"
  , "} pudu_callback_unobserved;"
  , ""
  , "static pudu_callback_entry *pudu_callbacks = NULL;"
  , "static pudu_callback_unobserved *pudu_callback_unobserved_first = NULL, **pudu_callback_unobserved_last = &pudu_callback_unobserved_first;"
  , "static uintptr_t pudu_callback_next = 1;"
  , "static atomic_int pudu_callbacks_closed = ATOMIC_VAR_INIT(0);"
  , "static _Thread_local pudu_callback_invocation *pudu_callback_active = NULL;"
  , "static _Thread_local pudu_callback_scope *pudu_callback_caller = NULL;"
  , "static void pudu_unwind_frames(void);"
  , "PUDU_OPTIONAL static pudu_cell pudu_run_callback(pudu_box *, const pudu_cell *, size_t, const pudu_site *);"
  , "static void pudu_callback_warn(const char *message, size_t length);"
  , ""
  , "PUDU_OPTIONAL static uintptr_t pudu_callback_register(const void *identity, pudu_box *handler,"
  , "                                                      void (*drop)(pudu_box *),"
  , "                                                      const size_t *fields, size_t members) {"
  , "  if (atomic_load(&pudu_callbacks_closed)) return 0;"
  , "  if (members > (SIZE_MAX - sizeof(pudu_callback_entry)) / sizeof(size_t)) pudu_memory_failure();"
  , "  pudu_callback_entry *entry = calloc(1, sizeof *entry + members * sizeof(size_t));"
  , "  if (entry == NULL || pudu_callback_next == 0) pudu_memory_failure();"
  , "  entry->key = pudu_callback_next++;"
  , "  entry->identity = identity;"
  , "  entry->handler = pudu_box_retain(handler);"
  , "  entry->drop = drop;"
  , "  entry->members = members;"
  , "  if (members != 0) memcpy(entry->fields, fields, members * sizeof(*fields));"
  , "  entry->next = pudu_callbacks;"
  , "  pudu_callbacks = entry;"
  , "  return entry->key;"
  , "}"
  , ""
  , "static pudu_callback_entry *pudu_callback_find(uintptr_t key) {"
  , "  pudu_callback_entry *entry = pudu_callbacks;"
  , "  while (entry != NULL && entry->key != key) entry = entry->next;"
  , "  return entry;"
  , "}"
  , ""
  , "static void pudu_callback_reclaim(pudu_callback_entry *entry) {"
  , "  if (entry->retired && entry->active == 0 && entry->leases == 0 && entry->handler != NULL) {"
  , "    entry->drop(entry->handler);"
  , "    entry->handler = NULL;"
  , "  }"
  , "}"
  , ""
  , "static void pudu_callback_dispose_closed(pudu_callback_entry *entry) {"
  , "  if (!atomic_load(&pudu_callbacks_closed) || entry->active || entry->leases || entry->waiters) return;"
  , "  pudu_callback_entry **link = &pudu_callbacks;"
  , "  while (*link != entry) link = &(*link)->next;"
  , "  *link = entry->next;"
  , "  if (entry->failed && !entry->observed) {"
  , "    pudu_callback_unobserved *held = malloc(sizeof *held);"
  , "    if (held == NULL) pudu_memory_failure();"
  , "    *held = (pudu_callback_unobserved){NULL, entry->failure, entry->failure_site};"
  , "    *pudu_callback_unobserved_last = held;"
  , "    pudu_callback_unobserved_last = &held->next;"
  , "  } else if (entry->failed) {"
  , "    pudu_text_release(entry->failure);"
  , "  }"
  , "  free(entry);"
  , "}"
  , ""
  , "PUDU_OPTIONAL static pudu_callback_entry *pudu_callback_lease(uintptr_t key, const void *identity) {"
  , "  pudu_callback_entry *entry = pudu_callback_find(key);"
  , "  if (entry == NULL || entry->identity != identity || entry->retired ||"
  , "      atomic_load(&pudu_callbacks_closed)) return NULL;"
  , "  ++entry->leases;"
  , "  return entry;"
  , "}"
  , ""
  , "PUDU_OPTIONAL static void pudu_callback_unlease(pudu_callback_entry *entry) {"
  , "  --entry->leases;"
  , "  pudu_callback_reclaim(entry);"
  , "  pudu_callback_dispose_closed(entry);"
  , "  pudu_host_changed();"
  , "}"
  , ""
  , "PUDU_OPTIONAL static int pudu_callback_unregister(uintptr_t key, pudu_text *failure) {"
  , "  pudu_callback_entry *entry = pudu_callback_find(key);"
  , "  if (entry == NULL) {"
  , "    *failure = pudu_text_literal(\"unknown callback token\", 22);"
  , "    return 0;"
  , "  }"
  , "  entry->retired = 1;"
  , "  int inside = 0;"
  , "  for (pudu_callback_invocation *held = pudu_callback_active; held; held = held->previous)"
  , "    if (held->entry == entry) { inside = 1; break; }"
  , "  ++entry->waiters;"
  , "  while (!inside && entry->active != 0) (void)pudu_host_wait(NULL);"
  , "  --entry->waiters;"
  , "  pudu_callback_reclaim(entry);"
  , "  int ok = !entry->failed;"
  , "  if (!ok) {"
  , "    entry->observed = 1;"
  , "    *failure = pudu_text_retain(entry->failure);"
  , "  }"
  , "  pudu_callback_dispose_closed(entry);"
  , "  return ok;"
  , "}"
  , ""
  , "PUDU_OPTIONAL static void pudu_callback_outbound_begin(pudu_callback_scope *scope) {"
  , "  *scope = (pudu_callback_scope){.previous = pudu_callback_caller};"
  , "  pudu_callback_caller = scope;"
  , "  pudu_host_leave();"
  , "}"
  , ""
  , "PUDU_OPTIONAL static void pudu_callback_outbound_end(pudu_callback_scope *scope) {"
  , "  pudu_host_enter();"
  , "  pudu_callback_caller = scope->previous;"
  , "}"
  , ""
  , "static void pudu_callback_trap(const pudu_site *site, const char *message,"
  , "                               size_t length, void *owned_payload) {"
  , "  pudu_callback_invocation *invocation = pudu_callback_active;"
  , "  if (invocation == NULL) return;"
  , "  if (!invocation->entry->failed) {"
  , "    invocation->entry->failure = pudu_text_copy(message, length);"
  , "    invocation->entry->failure_site = *site;"
  , "    invocation->entry->failed = 1;"
  , "  }"
  , "  free(owned_payload);"
  , "  pudu_unwind_frames();"
  , "  longjmp(invocation->escape, 1);"
  , "}"
  , ""
  , "static void pudu_callback_warn(const char *message, size_t length) {"
  , "  pudu_prepare_error_io();"
  , "  fputs(\"warning[W7027]: \", stderr);"
  , "  if (length != 0) fwrite(message, 1, length, stderr);"
  , "  fputc('\\n', stderr);"
  , "}"
  , ""
  , "/* Waiting callbacks may leave when admission closes, without leaving a"
  , "   gap in the ticket queue of production threads. */"
  , "static int pudu_callback_enter_gate(void) {"
  , "  pthread_mutex_lock(&pudu_gate_lock);"
  , "  pudu_gate_broadcast_waiters += 1;"
  , "  while (!atomic_load(&pudu_callbacks_closed) && pudu_gate_next != pudu_gate_serving)"
  , "    pthread_cond_wait(&pudu_gate_moved, &pudu_gate_lock);"
  , "  pudu_gate_broadcast_waiters -= 1;"
  , "  int entered = !atomic_load(&pudu_callbacks_closed);"
  , "  if (entered) ++pudu_gate_next;"
  , "  pthread_mutex_unlock(&pudu_gate_lock);"
  , "  return entered;"
  , "}"
  , ""
  , "/* The jump boundary uses the pinned invocation. Slot lookup and"
  , "   lifetime bookkeeping stay in its caller's ordinary frame. */"
  , "static int pudu_callback_protected(pudu_callback_invocation *invocation,"
  , "                                   pudu_box *handler, void (*body)(pudu_box *, void *), void *arguments) {"
  , "  if (setjmp(invocation->escape) != 0) return 0;"
  , "  body(handler, arguments);"
  , "  return 1;"
  , "}"
  , ""
  , "PUDU_OPTIONAL static int pudu_callback_invoke(uintptr_t key, const void *identity, size_t member,"
  , "                                             void (*body)(pudu_box *, void *), void *arguments) {"
  , "  if (!pudu_callback_enter_gate()) return 0;"
  , "  pudu_callback_entry *entry = atomic_load(&pudu_callbacks_closed) ? NULL : pudu_callback_find(key);"
  , "  if (entry == NULL || entry->identity != identity || entry->retired || entry->failed) {"
  , "    if (entry != NULL && entry->identity == identity && entry->retired && !entry->warned) {"
  , "      static const char message[] = \"a foreign library invoked a retired callback\";"
  , "      entry->warned = 1;"
  , "      pudu_callback_warn(message, sizeof message - 1);"
  , "    }"
  , "    pudu_host_leave();"
  , "    return 0;"
  , "  }"
  , "  if ((member == SIZE_MAX && entry->members != 0) || (member != SIZE_MAX && member >= entry->members)) {"
  , "    pudu_host_leave();"
  , "    return 0;"
  , "  }"
  , "  pudu_box *handler = member == SIZE_MAX ? entry->handler : entry->handler->fields[entry->fields[member]].box;"
  , "  ++entry->active;"
  , "  pudu_callback_invocation invocation;"
  , "  invocation.entry = entry;"
  , "  invocation.previous = pudu_callback_active;"
  , "  pudu_callback_active = &invocation;"
  , "  pudu_frame *saved_frame = pudu_active_frame;"
  , "  size_t saved_depth = pudu_frame_depth;"
  , "  pudu_active_frame = NULL;"
  , "  pudu_frame_depth = 0;"
  , "  int ok = pudu_callback_protected(&invocation, handler, body, arguments);"
  , "  if (!ok && pudu_callback_caller != NULL && !pudu_callback_caller->failed) {"
  , "    pudu_callback_caller->failure = pudu_text_retain(entry->failure);"
  , "    pudu_callback_caller->failure_site = entry->failure_site;"
  , "    pudu_callback_caller->failed = 1;"
  , "  }"
  , "  pudu_active_frame = saved_frame;"
  , "  pudu_frame_depth = saved_depth;"
  , "  pudu_callback_active = invocation.previous;"
  , "  --entry->active;"
  , "  pudu_callback_reclaim(entry);"
  , "  pudu_callback_dispose_closed(entry);"
  , "  pudu_host_changed();"
  , "  pudu_host_leave();"
  , "  return ok;"
  , "}"
  , ""
  , "/* A callback's failure during a foreign call fails the call once the"
  , "   crossing has settled, naming where the callback failed. */"
  , "PUDU_OPTIONAL static _Noreturn void pudu_callback_deliver(const pudu_site *call, pudu_callback_scope *scope) {"
  , "  static const char message[] = \"a nested foreign callback failed\";"
  , "  const pudu_site *failed = &scope->failure_site;"
  , "  size_t room = scope->failure.length + strlen(failed->file) + 64;"
  , "  char *note = malloc(room);"
  , "  if (note == NULL) pudu_memory_failure();"
  , "  int written = snprintf(note, room, \"%.*s (%s:%d:%d)\", (int)scope->failure.length,"
  , "                         (const char *)scope->failure.bytes, failed->file, failed->line, failed->column);"
  , "  pudu_text_release(scope->failure);"
  , "  scope->failure = (pudu_text){0};"
  , "  pudu_blame_hook = NULL;"
  , "  pudu_fail_noted(call, message, sizeof message - 1, note, written < 0 ? 0 : (size_t)written, NULL, 0, note);"
  , "}"
  , ""
  , "/* Warns of each failure nobody observed through its registration. */"
  , "PUDU_OPTIONAL static void pudu_callback_warn_unobserved(void) {"
  , "  static const char lead[] = \"foreign callback failed before teardown: \";"
  , "  while (pudu_callback_unobserved_first != NULL) {"
  , "    pudu_callback_unobserved *held = pudu_callback_unobserved_first;"
  , "    size_t length = sizeof lead - 1 + held->failure.length;"
  , "    char *message = malloc(length + 1);"
  , "    if (message == NULL) pudu_memory_failure();"
  , "    memcpy(message, lead, sizeof lead - 1);"
  , "    if (held->failure.length != 0) memcpy(message + sizeof lead - 1, held->failure.bytes, held->failure.length);"
  , "    pudu_prepare_error_io();"
  , "    pudu_render_report(\"warning\", \"\\x1b[33m\", \"W7027\", &held->site, message, length, NULL, 0, NULL, 0);"
  , "    free(message);"
  , "    pudu_callback_unobserved_first = held->next;"
  , "    pudu_text_release(held->failure);"
  , "    free(held);"
  , "  }"
  , "  pudu_callback_unobserved_last = &pudu_callback_unobserved_first;"
  , "}"
  , ""
  , "PUDU_OPTIONAL static void pudu_callback_enable(void) {"
  , "  pudu_gate_shared = 1;"
  , "  pudu_callback_trap_hook = pudu_callback_trap;"
  , "}"
  , ""
  , "PUDU_OPTIONAL static int pudu_callback_teardown(void) {"
  , "  if (atomic_exchange(&pudu_callbacks_closed, 1)) return 0;"
  , "  pudu_host_changed();"
  , "  struct timespec until = pudu_host_until(5000);"
  , "  for (pudu_callback_entry *entry = pudu_callbacks; entry; entry = entry->next) {"
  , "    entry->retired = 1;"
  , "    pudu_callback_reclaim(entry);"
  , "  }"
  , "  for (;;) {"
  , "    int active = 0;"
  , "    for (pudu_callback_entry *entry = pudu_callbacks; entry; entry = entry->next)"
  , "      if (entry->active) { active = 1; break; }"
  , "    if (!active || !pudu_host_wait(&until)) break;"
  , "  }"
  , "  for (pudu_callback_entry *entry = pudu_callbacks, *next; entry != NULL; entry = next) {"
  , "    next = entry->next;"
  , "    pudu_callback_dispose_closed(entry);"
  , "  }"
  , "  return 1;"
  , "}"
  ]
